<?php elseif($page==='app-edit'):$i=$c->instance((string)$_GET['id']);$cfg=$c->config($i['id']);?><section class="panel compact"><div class="panel-head"><?=h($i['name'])?></div><div class="panel-body"><form method="post" action="/?page=config-save"><input type="hidden" name="csrf" value="<?=h($c->csrf())?>"><input type="hidden" name="id" value="<?=h($i['id'])?>"><label>CSV-URL</label><input type="url" name="remoteUrl" value="<?=h($cfg['remoteUrl']??'')?>" required><label>Seitentitel</label><input name="title" value="<?=h($cfg['title']??'')?>" required><label>Überschrift</label><input name="heading" value="<?=h($cfg['heading']??'')?>" required><div class="form-grid"><div><label>Trennzeichen</label><select name="delimiter"><option value="," <?=($cfg['delimiter']??',')===','?'selected':''?>>Komma</option><option value=";" <?=($cfg['delimiter']??'')===';'?'selected':''?>>Semikolon</option><option value="\t" <?=($cfg['delimiter']??'')==='\t'?'selected':''?>>Tabulator</option></select></div><div><label>Timeout</label><input type="number" name="timeoutSeconds" min="2" max="60" value="<?=h($cfg['timeoutSeconds']??20)?>"></div><div><label>Refresh</label><input type="number" name="refreshSeconds" min="0" value="<?=h($cfg['refreshSeconds']??0)?>"></div><div><label><input style="width:auto" type="checkbox" name="hasHeader" <?=($cfg['hasHeader']??true)?'checked':''?>> Kopfzeile</label></div></div><label>Sichtbare Spalten, kommagetrennt</label><input name="showColumns" value="<?=h(implode(', ',$cfg['showColumns']??[]))?>"><label>Umbenennungen, je Zeile Original=Neu</label><textarea name="columnRenames"><?php foreach(($cfg['columnRenames']??[])as$k=>$v)echo h($k.'='.$v)."\n";?></textarea><label>Links, je Zeile Spalte=URL mit {value}</label><textarea name="columnLinks"><?php foreach(($cfg['columnLinks']??[])as$k=>$v)echo h($k.'='.$v)."\n";?></textarea><label><input style="width:auto" type="checkbox" name="mapEnabled" <?=!empty($cfg['map']['enabled'])?'checked':''?>> Map aktivieren</label><div class="form-grid"><div><label>Latitude-Spalte</label><input name="latitudeColumn" value="<?=h($cfg['map']['latitudeColumn']??'')?>"></div><div><label>Longitude-Spalte</label><input name="longitudeColumn" value="<?=h($cfg['map']['longitudeColumn']??'')?>"></div><div><label>Beschriftungsspalte</label><input name="labelColumn" value="<?=h($cfg['map']['labelColumn']??'')?>"></div></div><button style="margin-top:15px">Speichern</button></form></div></section>
<?php endif?></main></section></div></body></html>
